//! 🧮️ Actual shared provider backing, independent of semantic limits and retired ownership.
use super::{Cell,FloatColumn,Projection,ordered_row_refs,insert_ieee754,project_text,reconstruct_text,reconstruct_blob};
use super::super::{SqliteDatabaseLimits,SqliteSnapshotControl as Control,SqliteSnapshotPhase as Phase,SqliteSnapshotProgress,SqliteTable,SqliteRow,SqliteValue,ValueError,ValueRefusalKind};
use std::{alloc::{GlobalAlloc,Layout,System},cell::Cell as Local};

struct ObservedAllocator;
std::thread_local! { static OBSERVING: Local<bool> = const { Local::new(false) }; static REQUESTED: Local<usize> = const { Local::new(0) }; }
fn record(bytes:usize){let _=OBSERVING.try_with(|active|{if active.get(){let _=REQUESTED.try_with(|total|total.set(total.get().checked_add(bytes).unwrap()));}});}
unsafe impl GlobalAlloc for ObservedAllocator {
 unsafe fn alloc(&self,layout:Layout)->*mut u8{record(layout.size());unsafe{System.alloc(layout)}}
 unsafe fn alloc_zeroed(&self,layout:Layout)->*mut u8{record(layout.size());unsafe{System.alloc_zeroed(layout)}}
 unsafe fn realloc(&self,pointer:*mut u8,layout:Layout,size:usize)->*mut u8{record(size);unsafe{System.realloc(pointer,layout,size)}}
 unsafe fn dealloc(&self,pointer:*mut u8,layout:Layout){unsafe{System.dealloc(pointer,layout)}}
}
#[global_allocator]
static ALLOCATOR:ObservedAllocator=ObservedAllocator;
struct Observation;
impl Drop for Observation{fn drop(&mut self){OBSERVING.with(|active|active.set(false));}}
fn observe<T>(operation:impl FnOnce()->T)->(T,usize){REQUESTED.with(|total|total.set(0));OBSERVING.with(|active|{assert!(!active.replace(true));});let guard=Observation;let result=operation();drop(guard);(result,REQUESTED.with(Local::get))}
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🧮️allocation/🔣️.json")).unwrap()}
fn n(f:&serde_json::Value,key:&str)->usize{f[key].as_u64().unwrap()as usize}
fn limits(f:&serde_json::Value,allocation:usize)->SqliteDatabaseLimits{SqliteDatabaseLimits{max_allocation_bytes:allocation,max_value_bytes:n(f,"semanticBytes"),max_file_bytes:n(f,"fileBytes"),max_schema_bytes:n(f,"schemaBytes"),..Default::default()}}
fn ownership<T>(result:Result<T,ValueError>)->ValueError{match result{Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);error},Ok(_)=>panic!("provider must refuse concrete backing before allocation")}}
fn cancellation_diagnostic_bytes()->usize{let mut cancel=|_|false;Control::new(&mut cancel,SqliteDatabaseLimits::default()).checkpoint(Phase::ReconstructSnapshot,0,0).unwrap_err().message.capacity()}
fn schema_cost(f:&serde_json::Value)->usize{let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(f,n(f,"allocationBytes")));let(_,observed)=observe(||{let projection=Projection::new(f["schemaSql"].as_str().unwrap(),&mut control).unwrap();drop(projection);});let charged=n(f,"allocationBytes")-control.allocation_remaining_bytes();assert!(charged>0,"schema/table ownership must be admitted");assert_eq!(observed,charged,"every successful schema backing request needs admission");charged}
fn payloads(f:&serde_json::Value)->(String,Vec<u8>){(f["textUnit"].as_str().unwrap().repeat(n(f,"textRepeats")),f["blobUnit"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect::<Vec<_>>().repeat(n(f,"blobRepeats")))}
fn relation(ordinals:&[usize])->SqliteTable{SqliteTable{name:"provider_relation".into(),sql:"".into(),rows:ordinals.iter().enumerate().map(|(index,ordinal)|SqliteRow{rowid:index as i64+1,values:vec![SqliteValue::Integer(index as i64+1),SqliteValue::Integer(1),SqliteValue::Integer(*ordinal as i64),SqliteValue::Integer(7)]}).collect()}}

#[test]
fn shared_provider_allocation_schema_tables_exact_refused_repeated_and_canceled(){
 let f=fixture();let sql=f["schemaSql"].as_str().unwrap();
 for cap in f["tinyAllocationBytes"].as_array().unwrap(){let cap=cap.as_u64().unwrap()as usize;let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,cap));let(result,requested)=observe(||Projection::new(sql,&mut control).map(drop));let error=ownership(result);assert_eq!(requested,error.message.capacity(),"zero/tiny schema refusal may allocate only its typed error");assert_eq!(control.allocation_remaining_bytes(),cap);}
 let cost=schema_cost(&f);let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,cost*2));for _ in 0..2{drop(Projection::new(sql,&mut control).unwrap());}assert_eq!(control.allocation_remaining_bytes(),0);ownership(Projection::new(sql,&mut control).map(drop));
 let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,cost-1));ownership(Projection::new(sql,&mut control).map(drop));
 let interior=Local::new(false);let mut callback=|event:SqliteSnapshotProgress|{let stop=event.phase==Phase::ProjectSnapshot&&event.total==sql.len()&&event.completed>=256&&event.completed<event.total;interior.set(interior.get()||stop);!stop};let mut control=Control::new(&mut callback,limits(&f,n(&f,"allocationBytes")));let error=Projection::new(sql,&mut control).err().expect("schema producer must check interior cancellation");assert_eq!(error.kind,ValueRefusalKind::Canceled);assert!(interior.get());assert!(control.allocation_remaining_bytes()<n(&f,"allocationBytes"));
 eprintln!("[DEBUG] Shared schema/table requested backing {cost}");
}

#[test]
fn shared_provider_allocation_numeric_cells_and_rows_have_actual_exact_backing(){
 let f=fixture();let sql=f["schemaSql"].as_str().unwrap();let table=f["relationTable"].as_str().unwrap();let cells=[Cell::Integer(1),Cell::Integer(0),Cell::Integer(7)];let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,n(&f,"allocationBytes")));let mut projection=Projection::new(sql,&mut control).unwrap();let before=projection.control.allocation_remaining_bytes();let(result,requested)=observe(||projection.insert(table,&cells));result.unwrap();let cost=before-projection.control.allocation_remaining_bytes();assert!(cost>=4*std::mem::size_of::<SqliteValue>()+std::mem::size_of::<SqliteRow>());assert_eq!(cost,requested,"numeric-only cells and row Vec backing require admission");drop(projection);
 for allowance in [cost,cost-1,0]{let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,n(&f,"allocationBytes")));let mut projection=Projection::new(sql,&mut control).unwrap();projection.control.limits.max_allocation_bytes=projection.control.allocation_bytes+allowance;let(result,requested)=observe(||projection.insert(table,&cells));if allowance==cost{result.unwrap();assert_eq!(requested,cost);assert_eq!(projection.control.allocation_remaining_bytes(),0);}else{let error=ownership(result);assert_eq!(requested,allowance-projection.control.allocation_remaining_bytes()+error.message.capacity(),"refused cell/row frontier must not allocate");assert!(projection.database.table(table).unwrap().rows.is_empty());}}
 eprintln!("[DEBUG] Shared numeric cell/row requested backing {cost}");
}

#[test]
fn shared_provider_allocation_text_blob_exact_and_retired_copies_remain_cumulative(){
 let f=fixture();let(text,blob)=payloads(&f);let maximum=text.len()+blob.len();assert_eq!(text.len(),n(&f,"textBytes"));assert_eq!(blob.len(),n(&f,"blobBytes"));let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,maximum));let(result,requested)=observe(||Ok::<_,ValueError>((project_text(&mut control,&text)?,reconstruct_blob(&mut control,&blob)?)));let(owned_text,owned_blob)=result.unwrap();assert_eq!(owned_text.as_bytes(),text.as_bytes());assert_eq!(owned_blob.as_slice(),blob.as_slice());drop((owned_text,owned_blob));assert_eq!(requested,maximum);assert_eq!(control.allocation_remaining_bytes(),0);ownership(reconstruct_text(&mut control,"x"));
 let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,text.len()));let(owned_text,requested)=observe(||reconstruct_text(&mut control,&text).unwrap());assert_eq!(owned_text.as_bytes(),text.as_bytes());assert_eq!(requested,text.len());assert_eq!(control.allocation_remaining_bytes(),0);drop(owned_text);
 let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,maximum-1));drop(reconstruct_text(&mut control,&text).unwrap());ownership(reconstruct_blob(&mut control,&blob));assert_eq!(control.allocation_remaining_bytes(),blob.len()-1);
 let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,n(&f,"repeatedAllocationBytes")));for _ in 0..2{assert_eq!(reconstruct_text(&mut control,f["repeatedText"].as_str().unwrap()).unwrap(),f["repeatedText"].as_str().unwrap());}assert_eq!(control.allocation_remaining_bytes(),0);ownership(reconstruct_text(&mut control,f["repeatedText"].as_str().unwrap()));
 let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(&f,0));assert_eq!(project_text(&mut control,"").unwrap(),"");assert!(reconstruct_blob(&mut control,&[]).unwrap().is_empty());assert_eq!(control.allocation_remaining_bytes(),0);ownership(project_text(&mut control,"x"));ownership(reconstruct_blob(&mut control,&[1]));
 eprintln!("[DEBUG] Shared text/blob exact backing {maximum}, retired reconstruction copies remain cumulative");
}

#[test]
fn shared_provider_allocation_text_blob_interior_cancellation_retains_backing(){
 let f=fixture();let(text,blob)=payloads(&f);let diagnostic_bytes=cancellation_diagnostic_bytes();
 for binary in [false,true]{let total=if binary{blob.len()}else{text.len()};let cancellations=Local::new(0);let mut callback=|event:SqliteSnapshotProgress|{let stop=event.phase==Phase::ReconstructSnapshot&&event.total==total&&event.completed>=n(&f,"copyFrontier")&&event.completed<total;if stop{cancellations.set(cancellations.get()+1);}!stop};let mut control=Control::new(&mut callback,limits(&f,total));let(result,requested)=observe(||if binary{reconstruct_blob(&mut control,&blob).map(drop)}else{reconstruct_text(&mut control,&text).map(drop)});let error=result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(cancellations.get(),1);assert_eq!(control.allocation_remaining_bytes(),0,"late canceled field must retain its requested backing");assert_eq!(requested,total+diagnostic_bytes+error.message.capacity(),"only exact paid payload and the two actual typed diagnostics may allocate");ownership(reconstruct_text(&mut control,"x"));}
 let mut cancel=|_|false;let mut control=Control::new(&mut cancel,limits(&f,n(&f,"textBytes")));let error=project_text(&mut control,&text).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::Canceled);assert_eq!(control.allocation_remaining_bytes(),n(&f,"textBytes"));
 eprintln!("[DEBUG] Shared text/blob interior cancellation retains 100000 requested bytes per field");
}

