//! 🧮️ Actual shared provider backing, independent of semantic limits and retired ownership.
use super::{Cell,FloatColumn,Projection,ordered_row_refs,insert_ieee754,project_text,reconstruct_text,reconstruct_blob};
use super::super::{SqliteDatabaseLimits,SqliteSnapshotControl as Control,SqliteSnapshotPhase as Phase,SqliteSnapshotProgress,SqliteTable,SqliteRow,SqliteValue,ValueError,ValueRefusalKind};
use std::cell::Cell as Local;
use crate::test_allocation::observe;

fn fixture()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🧮️allocation/🔣️.json")).unwrap()}
fn n(f:&serde_json::Value,key:&str)->usize{f[key].as_u64().unwrap()as usize}
fn limits(f:&serde_json::Value,allocation:usize)->SqliteDatabaseLimits{SqliteDatabaseLimits{max_allocation_bytes:allocation,max_value_bytes:n(f,"semanticBytes"),max_file_bytes:n(f,"fileBytes"),max_schema_bytes:n(f,"schemaBytes"),..Default::default()}}
fn ownership<T>(result:Result<T,ValueError>)->ValueError{match result{Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::OwnershipLimit);error},Ok(_)=>panic!("provider must refuse concrete backing before allocation")}}
fn cancellation_diagnostic_bytes()->usize{let mut cancel=|_|false;Control::new(&mut cancel,SqliteDatabaseLimits::default()).checkpoint(Phase::ReconstructSnapshot,0,0).unwrap_err().message.capacity()}
fn schema_cost(f:&serde_json::Value)->usize{let mut accept=|_|true;let mut control=Control::new(&mut accept,limits(f,n(f,"allocationBytes")));let(_,observed)=observe(||{let projection=Projection::new(f["schemaSql"].as_str().unwrap(),&mut control).unwrap();drop(projection);});let charged=n(f,"allocationBytes")-control.allocation_remaining_bytes();assert!(charged>0,"schema/table ownership must be admitted");assert_eq!(observed,charged,"every successful schema backing request needs admission");charged}
fn payloads(f:&serde_json::Value)->(String,Vec<u8>){(f["textUnit"].as_str().unwrap().repeat(n(f,"textRepeats")),f["blobUnit"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect::<Vec<_>>().repeat(n(f,"blobRepeats")))}
fn relation(ordinals:&[usize])->SqliteTable{SqliteTable{name:"provider_relation".into(),sql:"".into(),rows:ordinals.iter().enumerate().map(|(index,ordinal)|SqliteRow{rowid:index as i64+1,values:vec![SqliteValue::Integer(index as i64+1),SqliteValue::Integer(1),SqliteValue::Integer(*ordinal as i64),SqliteValue::Integer(7)]}).collect()}}

